# Surah Yusuf (chapter 12) — part 4: ayat 31-40 (IDs 1627-1636)
SURAH = 12

ENTRIES = {
1627: (
"پس — جب — اس — نے — ان — عورتوں کی چال — سنی — اس نے — ان — کی طرف — پیغام — بھیجا — اور — اس نے — ان — کے لیے — ایک تخت والی جگہ — تیار کی — اور — ان — میں سے — ہر — ایک — کو — چھری — دی — اور — کہا — اس — کے سامنے آ جاؤ — پس — جب — ان — نے — اسے — دیکھا — تو — اسے بہت عظیم — خیال — کیا — اور — انہوں نے — اپنے — ہاتھ — کاٹ — لیے — اور — کہا — اللہ — پاک — ہے — یہ — کوئی انسان — نہیں — یہ — تو — ایک — عزت والے — فرشتہ — ہیں",
"""۱۔ عزیز کی بیوی — عورتوں — کو — مدعو — کرتی ہے؛ یوسفؑ کا حسن — سب — کو حیران کر دیتا ہے۔
۲۔ ’’فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ أَرْسَلَتْ إِلَيْهِنَّ وَأَعْتَدَتْ لَهُنَّ مُتَّكَأً وَآتَتْ كُلَّ وَاحِدَۃٍ مِّنْهُنَّ سِكِّينًا وَقَالَتِ اخْرُجْ عَلَيْهِنَّ فَلَمَّا رَأَيْنَهُ أَكْبَرْنَهُ وَقَطَّعْنَ أَيْدِيَهُنَّ وَقُلْنَ حَاشَ لِلَّهِ مَا هَٰذَا بَشَرًا إِنْ هَٰذَا إِلَّا مَلَكٌ كَرِيمٌ‘‘ — پس — جب — اس — نے — ان — عورتوں کی چال — سنی — اس نے — ان — کی طرف — پیغام — بھیجا — اور — اس نے — ان — کے لیے — ایک تخت والی جگہ — تیار کی — اور — ان — میں سے — ہر — ایک — کو — چھری — دی — اور — کہا — اس — کے سامنے آ جاؤ — پس — جب — ان — نے — اسے — دیکھا — تو — اسے بہت عظیم — خیال — کیا — اور — انہوں نے — اپنے — ہاتھ — کاٹ — لیے — اور — کہا — اللہ — پاک — ہے — یہ — کوئی انسان — نہیں — یہ — تو — ایک — عزت والے — فرشتہ — ہیں — یعنی جب — عزیز کی بیوی — نے ان عورتوں کی — چال سنی — اس نے — ان کی طرف پیغام — بھیجا — اور — اس — کے — لیے — ایک — تخت والی جگہ — بنائی — اور — ان — میں — سے ہر ایک کو — چھری — دی — اور کہا — اس کے سامنے آ جاؤ — پس — جب — ان — نے — اسے — دیکھا — تو — وہ — اسے — عظیم — سمجھیں — اور اپنے — ہاتھ — کاٹ لیں — اور — کہا — اللہ — پاک ہے — یہ کوئی انسان — نہیں — یہ — ایک — عزت والا فرشتہ — ہے۔
۳۔ عملی سبق: سچی شخصیت — دیکھنے والوں کو — متاثر — کرتی ہے۔"""
),
1628: (
"اس — نے کہا — تو — یہ — وہ — ہے — جس — پر — تم نے — مجھے — ملامت کی — یقیناً — میں — نے — اس — سے — اپنی — بات کی — مگر — وہ — بچ — گیا — اور — اگر — وہ — وہ — کام — نہ کرے — جو — میں — اسے — حکم — دوں — تو — وہ — ضرور — قید — کیا جائے گا — اور — وہ — بے عزت — لوگوں — میں — سے — ہے",
"""۱۔ عزیز کی بیوی — اپنا — ارتکاب — کرتی ہے — اور قید کی دھمکی دیتی ہے۔
۲۔ ’’قَالَتْ فَذَٰلِكُنَّ الَّذِي لُمْتُنَّنِي فِيهِ وَلَقَدْ رَاوَدتُّهُ عَن نَّفْسِهِ فَاسْتَعْصَمَ وَلَئِن لَّمْ يَفْعَلْ مَا آمُرُهُ لَيُسْجَنَنَّ وَلَيَكُونًا مِّنَ الصَّاغِرِينَ‘‘ — اس — نے کہا — تو — یہ — وہ — ہے — جس — پر — تم نے — مجھے — ملامت کی — یقیناً — میں — نے — اس — سے — اپنی — بات کی — مگر — وہ — بچ — گیا — اور — اگر — وہ — وہ — کام — نہ کرے — جو — میں — اسے — حکم — دوں — تو — وہ — ضرور — قید — کیا جائے گا — اور — وہ — بے عزت — لوگوں — میں — سے — ہے — یعنی عزیز کی بیوی — نے کہا — تو — یہ — وہ — ہے جس — پر تم مجھے — ملامت — کرتی تھیں — یقیناً — میں نے اس سے اپنی — بات کی — مگر — وہ — بچ — گیا — اور اگر — وہ — وہ — کام — نہ کرے جو میں اسے — حکم — دیاں — تو — وہ — ضرور — قید — کیا جائے گا — اور — وہ — بے عزت — لوگوں — میں — سے — ہو گا۔
۳۔ عملی سبق: طاقتور — غلط — بھی کرے — مگر — حق — کا ساتھ — دینا ضروری ہے۔"""
),
1629: (
"انہوں نے کہا — اے میرے رب — میرے لیے — قید — اس — سے — زیادہ — عزیز ہے — جو — یہ — مجھے — دعوت — دیتی ہیں — اور — اگر — تو — مجھ سے — ان — کی چال — کو — نہیں — ہٹائے — گا — تو — میں — ان — کی طرف — مائل — ہو — جاؤں گا — اور — میں — جاہلوں — میں — سے ہوں",
"""۱۔ یوسفؑ — اللہ — سے پناہ مانگتے ہیں — قید کو — ترجیح — دیتے ہیں۔
۲۔ ’’قَالَ رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِي إِلَيْهِ وَإِلَّا تَصْرِفْ عَنِّي كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ الْجَاهِلِينَ‘‘ — انہوں نے کہا — اے میرے رب — میرے لیے — قید — اس — سے — زیادہ — عزیز ہے — جو — یہ — مجھے — دعوت — دیتی ہیں — اور — اگر — تو — مجھ سے — ان — کی چال — کو — نہیں — ہٹائے — گا — تو — میں — ان — کی طرف — مائل — ہو — جاؤں گا — اور — میں — جاہلوں — میں — سے ہوں — یعنی یوسفؑ نے — کہا — اے میرے رب — میرے — لیے — قید — اس سے — زیادہ — عزیز — ہے — جس — کی طرف — یہ — مجھے — دعوت — دیتی ہیں — اور — اگر — تو — مجھ سے — ان — کی چال — کو — دور — نہیں کرے — گا — تو — میں ان — کی طرف — مائل — ہو — جاؤں گا — اور — میں — جاہلوں — میں — سے — ہوں۔
۳۔ عملی سبق: اللہ — سے — پناہ — مانگیں؛ قید — بھی — گناہ — سے بہتر ہے۔"""
),
1630: (
"پس — اس کا رب — نے — اس کی دعا قبول کی — اور — اس سے — ان — کی چال — کو — ہٹا دیا — بے شک — وہ — سننے — والا — جاننے — والا — ہے",
"""۱۔ اللہ — نے — یوسفؑ — کی — دعا — قبول کی۔
۲۔ ’’فَاسْتَجَابَ لَهُ رَبُّهُ فَصَرَفَ عَنْهُ كَيْدَهُنَّ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ‘‘ — پس — اس کا رب — نے — اس کی دعا قبول کی — اور — اس سے — ان — کی چال — کو — ہٹا دیا — بے شک — وہ — سننے — والا — جاننے — والا — ہے — یعنی پس — اس — کے رب نے — اس کی — دعا قبول کر لی — اور — اس — سے — ان — کی چال — کو — ہٹا — دیا — بے شک — وہ — سننے والا — جاننے والا — ہے۔
۳۔ عملی سبق: اللہ — دعا — سنتا ہے؛ ہو — حق پر ثابت — رہیں۔"""
),
1631: (
"پھر — انہیں — سوجھ — آیا — نشانیاں دیکھنے کے بعد — کہ — اسے — ایک مقرر — مدت تک — قید — کر دیں",
"""۱۔ عزیز — ثبوت کے باوجود — یوسفؑ کو — قید — کر دیتا ہے۔
۲۔ ’’ثُمَّ بَدَا لَهُم مِّن بَعْدِ مَا رَأَوُا الْآيَاتِ لَيَسْجُنُنَّهُ حَتَّىٰ حِينٍ‘‘ — پھر — انہیں — سوجھ — آیا — نشانیاں دیکھنے کے بعد — کہ — اسے — ایک مقرر — مدت تک — قید — کر دیں — یعنی پھر — بعد میں — ثبوت — دیکھنے کے باوجود — انہیں — سوجھ — آیا — کہ — اسے — ایک — مقرر — مدت — تک — قید — کر — دیں۔
۳۔ عملی سبق: ثبوت — کے باوجود — ظالم — اکثر — بے گناہ — کو — قید — کر دیتے ہیں۔"""
),
1632: (
"اور — اس — کے ساتھ — جیل — میں — دو جوان — داخل ہوئے — ان — میں سے ایک نے کہا — میں — نے — خود کو — انگور — نچوڑتے — دیکھا — اور — دوسرے — نے کہا — میں نے — خود کو — اپنے سر — کے اوپر — روٹی — اٹھائے دیکھا — پرندے — اس میں سے — کھا رہے ہیں — ہمیں — اس — کی — تعبیر — بتا دیں — بے شک — ہم — آپ کو — نیکوکار — لوگ — دیکھتے ہیں",
"""۱۔ جیل میں — دو — جوان — یوسفؑ — سے خواب کی تعبیر — پوچھتے ہیں۔
۲۔ ’’وَدَخَلَ مَعَهُ السِّجْنَ فَتَيَانِ قَالَ أَحَدُهُمَا إِنِّي أَرَانِي أَعْصِرُ خَمْرًا وَقَالَ الْآخَرُ إِنِّي أَرَانِي أَحْمِلُ فَوْقَ رَأْسِي خُبْزًا تَأْكُلُ الطَّيْرُ مِنْهُ نَبِّئْنَا بِتَأْوِيلِهِ إِنَّا نَرَاكَ مِنَ الْمُحْسِنِينَ‘‘ — اور — اس — کے ساتھ — جیل — میں — دو جوان — داخل ہوئے — ان — میں سے ایک نے کہا — میں — نے — خود کو — انگور — نچوڑتے — دیکھا — اور — دوسرے — نے کہا — میں نے — خود کو — اپنے سر — کے اوپر — روٹی — اٹھائے دیکھا — پرندے — اس میں سے — کھا رہے ہیں — ہمیں — اس — کی — تعبیر — بتا دیں — بے شک — ہم — آپ کو — نیکوکار — لوگ — دیکھتے ہیں — یعنی اس کے ساتھ — جیل — میں — دو جوان — آئے — ان — میں سے ایک — نے کہا — میں نے — خود کو — انگور — نچوڑتے — دیکھا — اور — دوسرے — نے کہا — میں نے — خود کو — اپنے سر — کے اوپر — روٹی — اٹھائے دیکھا — پرندے — اس میں سے — کھا رہے ہیں — ہمیں — اس — کی تعبیر — بتا دیں — بے شک ہم — آپ کو — نیکوکار — لوگ — دیکھتے ہیں۔
۳۔ عملی سبق: نیکی — کا اثر — سب دیکھتے ہیں؛ اسے — برقرار — رکھیں۔"""
),
1633: (
"انہوں نے — کہا — تمہارے پاس — کوئی کھانا — نہیں پہنچے گا — جو — تمہیں — دیا جائے — مگر میں — اس — کی تعبیر — اس کے آنے — سے پہلے — بتا دوں گا — یہ — اس — چیز — میں سے ہے — جو — میرے رب — نے — مجھے — سکھائی — بے شک — میں نے — ان لوگوں — کا دین — ترک کر دیا — جو — اللہ پر ایمان نہیں لاتے — اور — آخرت — سے — منکر ہیں",
"""۱۔ یوسفؑ — خواب کی تعبیر — اللہ کی تعلیم — سے بتاتے ہیں۔
۲۔ ’’قَالَ لَا يَأْتِيكُمَا طَعَامٌ تُّرْزَقَانِهِ إِلَّا نَبَّأْتُكُمَا بِتَأْوِيلِهِ قَبْلَ أَن يَأْتِيَكُمَا ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّي إِنِّي تَرَكْتُ مِلَّۃَ قَوْمٍ لَّا يُؤْمِنُونَ بِاللَّهِ وَهُم بِالْآخِرَۃِ هُمْ كَافِرُونَ‘‘ — انہوں نے — کہا — تمہارے پاس — کوئی کھانا — نہیں پہنچے گا — جو — تمہیں — دیا جائے — مگر میں — اس — کی تعبیر — اس کے آنے — سے پہلے — بتا دوں گا — یہ — اس — چیز — میں سے ہے — جو — میرے رب — نے — مجھے — سکھائی — بے شک — میں نے — ان لوگوں — کا دین — ترک کر دیا — جو — اللہ پر ایمان نہیں لاتے — اور — آخرت — سے — منکر ہیں — یعنی یوسفؑ نے — کہا — تمہارے پاس — کوئی کھانا — نہیں پہنچے گا — مگر میں — اس — کی تعبیر — اس — کے آنے — سے پہلے — بتا دوں گا — یہ — میرے رب — کی — سکھائی ہوئی چیز — ہے؛ میں نے — ان لوگوں — کا دین — چھوڑ دیا — جو اللہ پر ایمان نہیں لاتے — اور آخرت — سے منکر — ہیں۔
۳۔ عملی سبق: علم — اللہ کی طرف سے — آتا ہے؛ اس کی حفاظت — کریں۔"""
),
1634: (
"اور — میں نے — اپنے باپ دادا — ابراہیم، اسحاق اور یعقوبؑ — کے — دین — کی پیروی کی — ہمیں — کچھ — بھی — اختیار — نہیں — کہ ہم — اللہ کے ساتھ — کسی — چیز — کو شریک ٹھہرائیں — یہ — اللہ کا فضل ہے — ہم پر اور تمام لوگوں پر — لیکن — اکثر لوگ — شکر — نہیں کرتے",
"""۱۔ یوسفؑ — توحید کے وارث — ابراہیم، اسحاق اور یعقوبؑ — کا دین — مانتے ہیں۔
۲۔ ’’وَاتَّبَعْتُ مِلَّۃَ آبَائِي إِبْرَاهِيمَ وَإِسْحَاقَ وَيَعْقُوبَ مَا كَانَ لَنَا أَن نُّشْرِكَ بِاللَّهِ مِن شَيْءٍ ذَٰلِكَ مِن فَضْلِ اللَّهِ عَلَيْنَا وَعَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ‘‘ — اور — میں نے — اپنے باپ دادا — ابراہیم، اسحاق اور یعقوبؑ — کے — دین — کی پیروی کی — ہمیں — کچھ — بھی — اختیار — نہیں — کہ ہم — اللہ کے ساتھ — کسی — چیز — کو شریک ٹھہرائیں — یہ — اللہ کا فضل ہے — ہم پر اور تمام لوگوں پر — لیکن — اکثر لوگ — شکر — نہیں کرتے — یعنی میں — نے — اپنے باپ دادا — ابراہیم، اسحاق اور یعقوبؑ — کے دین — کی پیروی — کی؛ ہمیں — کچھ بھی اختیار — نہیں — کہ ہم — اللہ — کے ساتھ — کسی چیز — کو شریک — ٹھہرائیں؛ یہ — اللہ — کا فضل — ہے — ہم — پر اور تمام — لوگوں — پر — لیکن — اکثر — لوگ — شکر — نہیں — کرتے۔
۳۔ عملی سبق: توحید — خالص — دین — ہے؛ شکر — کرو۔"""
),
1635: (
"اے میرے جیل کے ساتھی — کیا — مختلف — معبود — بہتر ہیں — یا — اللہ — اکیلا — سب پر غالب",
"""۱۔ یوسفؑ — دو ساتھیوں — کو — توحید — کی تعلیم دیتے ہیں۔
۲۔ ’’يَا صَاحِبَيِ السِّجْنِ أَأَرْبَابٌ مُّتَفَرِّقُونَ خَيْرٌ أَمِ اللَّهُ الْوَاحِدُ الْقَهَّارُ‘‘ — اے میرے جیل کے ساتھی — کیا — مختلف — معبود — بہتر ہیں — یا — اللہ — اکیلا — سب پر غالب — یعنی اے — میرے جیل کے ساتھ — کیا — مختلف — معبود — بہتر — ہیں یا — اللہ — اکیلا — سب — پر غالب۔
۳۔ عملی سبق: توحید — سب سے — بڑی عقلیت — ہے۔"""
),
1636: (
"تم — اللہ — کے سوا — جس کی — عبادت کرتے ہو — اس — کے — سوا — صرف — نام ہیں — جنہیں — تم نے — اور — تمہارے باپ دادا — نے — خود — رکھ — لیے ہیں — اللہ — نے — ان — پر — کوئی — دلیل — نازل نہیں کی — فیصلہ — صرف اللہ کا — ہے — اس نے — حکم — دیا — کہ تم — اس — کے سوا — کسی کی عبادت — نہ کرو — یہی — درست — دین — ہے — لیکن — اکثر لوگ — نہیں جانتے",
"""۱۔ بت — صرف نام — ہیں؛ فیصلہ — صرف اللہ کا ہے۔
۲۔ ’’مَا تَعْبُدُونَ مِن دُونِهِ إِلَّا أَسْمَاءً سَمَّيْتُمُوهَا أَنتُمْ وَآبَاؤُكُم مَّا أَنزَلَ اللَّهُ بِهَا مِن سُلْطَانٍ إِنِ الْحُكْمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ ذَٰلِكَ الدِّينُ الْقَيِّمُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ‘‘ — تم — اللہ — کے سوا — جس کی — عبادت کرتے ہو — اس — کے — سوا — صرف — نام ہیں — جنہیں — تم نے — اور — تمہارے باپ دادا — نے — خود — رکھ — لیے ہیں — اللہ — نے — ان — پر — کوئی — دلیل — نازل نہیں کی — فیصلہ — صرف اللہ کا — ہے — اس نے — حکم — دیا — کہ تم — اس — کے سوا — کسی کی عبادت — نہ کرو — یہی — درست — دین — ہے — لیکن — اکثر لوگ — نہیں جانتے — یعنی تم — اللہ — کے سوا — جس کی — عبادت کرتے ہو — وہ — صرف — نام ہیں — جو — تم — اور تمہارے باپ دادا — نے رکھ — لیے ہیں — اللہ — نے — ان پر — کوئی — دلیل — نازل نہیں کی — فیصلہ — صرف — اللہ — کا ہے — اس — نے — حکم دیا — کہ — تم — اس کے سوا — کسی — کی عبادت — نہ کرو — یہی — درست — دین — ہے — لیکن — اکثر — لوگ — نہیں جانتے۔
۳۔ عملی سبق: اپنے — باپ دادا کی — بات — پر بھی — دلیل — مانگو؛ حق — پر قائم — رہو۔"""
),
}
